import java.io.*;

public class Main {
    static final long MOD = 998244353L;
    static long[] fact, invFact;

    static long modPow(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) != 0) result = result * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }

    static long combination(int n, int k) {
        if (k < 0 || k > n || n < 0) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int p = fs.nextInt();
        int s = fs.nextInt();
        int r = fs.nextInt();

        int maxN = s + p;
        fact = new long[maxN + 1];
        invFact = new long[maxN + 1];

        fact[0] = 1;
        for (int i = 1; i <= maxN; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }

        invFact[maxN] = modPow(fact[maxN], MOD - 2);
        for (int i = maxN; i >= 1; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        long total = combination(s + p - 1, p - 1);
        long bounded = 0;

        if (r > 0) {
            int limit = Math.min(p, s / r);
            for (int j = 0; j <= limit; j++) {
                long term = combination(p, j)
                        * combination(s - j * r + p - 1, p - 1) % MOD;
                if ((j & 1) == 0) {
                    bounded += term;
                    if (bounded >= MOD) bounded -= MOD;
                } else {
                    bounded -= term;
                    if (bounded < 0) bounded += MOD;
                }
            }
        }

        long favorableWeighted = (total - bounded + MOD) % MOD;
        favorableWeighted = favorableWeighted * modPow(p, MOD - 2) % MOD;

        long stateCount = combination(s - r + p - 1, p - 1);
        long answer = favorableWeighted * modPow(stateCount, MOD - 2) % MOD;

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }
}

