import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;
    static long[] fact, invFact, inv;

    static long modPow(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) != 0) result = result * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }

    static long combination(int n, int k) {
        if (k < 0 || k > n || n < 0) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    static long boundedCompositions(int variables, int sum, int x) {
        if (variables == 0) return sum == 0 ? 1 : 0;
        if (sum < 0 || (long) sum > (long) variables * (x - 1)) return 0;

        int limit = Math.min(variables, sum / x);
        long result = 0;

        for (int j = 0; j <= limit; j++) {
            int remaining = sum - j * x;
            long term = combination(variables, j)
                    * combination(remaining + variables - 1, variables - 1) % MOD;

            if ((j & 1) == 0) {
                result += term;
                if (result >= MOD) result -= MOD;
            } else {
                result -= term;
                if (result < 0) result += MOD;
            }
        }
        return result;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int p = fs.nextInt();
        int s = fs.nextInt();
        int r = fs.nextInt();

        int maxN = s + p + 5;
        fact = new long[maxN];
        invFact = new long[maxN];
        inv = new long[p + 1];

        fact[0] = 1;
        for (int i = 1; i < maxN; i++) fact[i] = fact[i - 1] * i % MOD;

        invFact[maxN - 1] = modPow(fact[maxN - 1], MOD - 2);
        for (int i = maxN - 1; i > 0; i--) {
            invFact[i - 1] = invFact[i] * i % MOD;
        }

        for (int i = 1; i <= p; i++) {
            inv[i] = modPow(i, MOD - 2);
        }

        int opponents = p - 1;
        long winningWeight = 0;

        for (int score = r; score <= s; score++) {
            if (score == 0) {
                if (s == 0) winningWeight = (winningWeight + inv[p]) % MOD;
                continue;
            }

            for (int tied = 0; tied <= opponents; tied++) {
                int remainingSum = s - (tied + 1) * score;
                if (remainingSum < 0) break;

                int remainingPlayers = opponents - tied;
                long count = boundedCompositions(remainingPlayers, remainingSum, score);
                if (count == 0) continue;

                long waysToChooseTied = combination(opponents, tied);
                long contribution = waysToChooseTied * count % MOD
                        * inv[tied + 1] % MOD;

                winningWeight += contribution;
                if (winningWeight >= MOD) winningWeight -= MOD;
            }
        }

        long totalStates = combination(s - r + p - 1, p - 1);
        long answer = winningWeight * modPow(totalStates, MOD - 2) % MOD;
        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0, length = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value * sign;
        }
    }
}
